import json
def C(title,scen,prompt,cues,target,eng,can):
    return {"tier":"tier1","level":"B2","title":"Communicative Challenge: "+title,"scenario":scen,"prompt":prompt,"cues":cues,"target":target,"english":eng,"canDo":can}
d={
"b2-perucosta-01":C("Why It Hardly Rains","You are Meg. You and Carlos are watching a documentary about Peru's coast, and he asks why it almost never rains there.","Tell Carlos why it hardly rains on the coast, giving the cause formally.",["Give the cause with a formal connector","Say that it hardly rains"],"Debido a la corriente fría, casi no llueve en la costa.","Because of the cold current, it hardly rains on the coast.","I can explain a cause formally with *debido a* and *a raíz de* + noun."),
"b2-perucosta-02":C("When Lima Was Founded","You are Carlos. You and Meg are reading about colonial Lima, and she asks when the city was founded.","Tell Meg when Lima was founded, using the passive.",["Say what was done","Give the date"],"Lima fue fundada el 18 de enero de 1535.","Lima was founded on 18 January 1535.","I can say what was founded, listed or proclaimed with the passive (*fue fundada*, *fueron incluidos*)."),
"b2-perucosta-03":C("Even If the Origin Is Unknown","You are Meg. You and Carlos are reading about the cajón for a short talk, and he asks whether anyone knows how it was born.","Tell Carlos that even if its exact origin is not known, the cajón is part of Peruvian music.",["Grant the point about the origin","Say what the cajón is part of"],"Aun cuando no se sepa su origen exacto, el cajón es parte de la música peruana.","Even if its exact origin is not known, the cajón is part of Peruvian music.","I can grant a point with *aun cuando* + indicative or subjunctive."),
"b2-perucosta-04":C("How Cebiche Is Served","You are Carlos. You and Meg are planning to try Peruvian food, and she asks how cebiche is served.","Tell Meg how cebiche is served, using the passive with se.",["Say what is served","Say how it is served"],"Los cebiches se sirven fríos.","Cebiches are served cold.","I can choose between passive and impersonal *se* (*se sirven los cebiches*, *se invitó a los vecinos*)."),
"b2-perucosta-05":C("A Report I Should Have Read","You are Meg. You and Carlos are preparing a talk about the rubber boom, and he asks if you read Casement's report.","Tell Carlos that you regret not having read Casement's report earlier.",["Express your regret","Mention the report"],"Me arrepiento de no haber leído antes el informe de Casement.","I regret not having read Casement's report earlier.","I can express regrets and reproaches with *debería haber* and *me arrepiento de haber* + participle."),
"b2-perucosta-consolidation":C("Peru in Review","You are Carlos. You and Meg are preparing a short talk about Peru, and she asks how to explain that the coast has fewer fish in some years.","Tell Meg that because of El Niño there is less anchoveta, giving the cause formally.",["Give the cause with a formal connector","Say that there is less anchoveta"],"Debido a El Niño, hay menos anchoveta en la costa.","Because of El Niño, there is less anchoveta on the coast.","I can explain a cause formally with *debido a* and *a raíz de* + noun."),
}
